from pathlib import Path

onboarding_path = Path('artifacts/api-server/src/routes/onboarding.ts')
tenants_path = Path('artifacts/api-server/src/routes/tenants.ts')
dashboard_path = Path('artifacts/frontend/src/pages/Dashboard.tsx')

onboarding = onboarding_path.read_text()
tenants = tenants_path.read_text()
dashboard = dashboard_path.read_text()

# ── Backend onboarding assistant ──────────────────────────────────────────────
onboarding = onboarding.replace('import { eq, and } from "drizzle-orm";', 'import { eq, and, count } from "drizzle-orm";', 1)
onboarding = onboarding.replace('''  businessProfilesTable,\n  agentConfigsTable,''', '''  businessProfilesTable,\n  agentConfigsTable,\n  leadsTable,''', 1)

import_anchor = 'import { getGoogleAdsConnectionByTenantId } from "../services/google-ads-oauth.js";'
if import_anchor not in onboarding:
    raise SystemExit('ai import anchor not found')
onboarding = onboarding.replace(import_anchor, import_anchor + '\nimport { callOpenAI } from "../lib/ai-gateway.js";', 1)

assistant_anchor = '''// ── GET /onboarding/integracoes ────────────────────────────────────────────────\nrouter.get("/onboarding/integracoes", authenticate, async (req, res) => {'''
if assistant_anchor not in onboarding:
    raise SystemExit('onboarding integrations anchor not found')

assistant_route = '''// ── POST /onboarding/assistant ────────────────────────────────────────────────\n// Agente de Implantação: usa o mesmo comportamento do agente onboarding e o\n// status REAL do tenant para orientar a próxima ação. Não cria dados nem marca\n// etapas como concluídas — apenas acompanha e explica o setup.\nrouter.post("/onboarding/assistant", authenticate, async (req, res) => {\n  const tenantId = req.user!.tenantId;\n  if (!tenantId) return res.status(403).json({ error: "Tenant não identificado" });\n\n  const parsed = z.object({ message: z.string().trim().min(1).max(2000) }).safeParse(req.body);\n  if (!parsed.success) return res.status(422).json({ error: "Mensagem inválida" });\n\n  const [[tenant], [profile], [config], [leadCountRow]] = await Promise.all([\n    db.select({\n      name: tenantsTable.name,\n      isDemo: tenantsTable.isDemo,\n      setupCompletedAt: tenantsTable.setupCompletedAt,\n      onboardingConcluido: tenantsTable.onboardingConcluido,\n    }).from(tenantsTable).where(eq(tenantsTable.id, tenantId)).limit(1),\n    db.select({ id: businessProfilesTable.id, produtos: businessProfilesTable.produtos })\n      .from(businessProfilesTable).where(eq(businessProfilesTable.tenantId, tenantId)).limit(1),\n    db.select({\n      setupCompletedAt: agentConfigsTable.setupCompletedAt,\n      autonomyEnabledAt: agentConfigsTable.autonomyEnabledAt,\n      metaPhoneNumberId: agentConfigsTable.metaPhoneNumberId,\n      metaAccessToken: agentConfigsTable.metaAccessToken,\n      evolutionConnected: agentConfigsTable.evolutionConnected,\n      instagramPageId: agentConfigsTable.instagramPageId,\n      instagramPageAccessToken: agentConfigsTable.instagramPageAccessToken,\n      webhookSecret: agentConfigsTable.webhookSecret,\n    }).from(agentConfigsTable).where(eq(agentConfigsTable.tenantId, tenantId)).limit(1),\n    db.select({ value: count() }).from(leadsTable).where(eq(leadsTable.tenantId, tenantId)),\n  ]);\n\n  if (!tenant) return res.status(404).json({ error: "Tenant não encontrado" });\n\n  const productsConfigured = Array.isArray(profile?.produtos) && profile.produtos.length > 0;\n  const whatsappConnected = !!(\n    (config?.metaPhoneNumberId && config?.metaAccessToken) || config?.evolutionConnected\n  );\n  const steps = [\n    { key: "onboarding", label: "Concluir o onboarding inicial", done: !!(tenant.setupCompletedAt || tenant.onboardingConcluido), href: "/onboarding" },\n    { key: "perfil", label: "Configurar o perfil da empresa", done: !!profile, href: "/configuracoes" },\n    { key: "produtos", label: "Cadastrar produtos ou serviços", done: productsConfigured, href: "/estoque" },\n    { key: "agentes", label: "Configurar os agentes de IA", done: !!config?.setupCompletedAt, href: "/configuracoes" },\n    { key: "whatsapp", label: "Conectar o WhatsApp", done: whatsappConnected, href: "/onboarding/integracoes" },\n    { key: "webhook", label: "Ativar o webhook de entrada", done: !!config?.webhookSecret, href: "/configuracoes" },\n    { key: "instagram", label: "Conectar o Instagram", done: !!(config?.instagramPageId && config?.instagramPageAccessToken), href: "/onboarding/integracoes" },\n    { key: "lead", label: "Cadastrar o primeiro lead real", done: Number(leadCountRow?.value ?? 0) > 0, href: "/leads" },\n    { key: "autonomia", label: "Habilitar a autonomia dos agentes", done: !!config?.autonomyEnabledAt, href: "/configuracoes" },\n  ];\n  const nextAction = steps.find((step) => !step.done) ?? null;\n  const completed = steps.filter((step) => step.done).length;\n\n  const statusText = steps.map((step) => `${step.done ? "✓" : "○"} ${step.label}`).join("\\n");\n  const systemPrompt = `${AGENT_BEHAVIOR_TEMPLATES.onboarding}\n\n` +\n    `Você também é o Agente de Implantação do VendorAI. Sua missão é acompanhar a configuração do sistema com base EXCLUSIVAMENTE no status real fornecido. ` +\n    `Nunca diga que uma etapa está concluída se ela estiver marcada como pendente. Não invente integrações ou dados. ` +\n    `Responda em português do Brasil, de forma curta, prática e acolhedora. Quando fizer sentido, indique UMA próxima ação concreta e explique onde clicar. ` +\n    `Se o cliente perguntar sobre algo fora da implantação, responda brevemente e traga o foco de volta para a ativação da plataforma.`;\n\n  try {\n    const result = await callOpenAI(\n      tenantId,\n      "agent_onboarding",\n      [\n        { role: "system", content: systemPrompt },\n        {\n          role: "user",\n          content: `EMPRESA: ${tenant.name}\\nTIPO: ${tenant.isDemo ? "Demo/Trial" : "Cliente ativo"}\\nPROGRESSO: ${completed}/${steps.length}\\n\\nSTATUS REAL:\\n${statusText}\\n\\nPRÓXIMA AÇÃO CALCULADA: ${nextAction?.label ?? "Implantação concluída"}\\n\\nPERGUNTA DO CLIENTE: ${parsed.data.message}`,\n        },\n      ],\n      { temperature: 0.3, maxTokens: 450, log: req.log },\n    );\n\n    return res.json({\n      resposta: result.content,\n      progress: { completed, total: steps.length },\n      nextAction: nextAction ? { key: nextAction.key, label: nextAction.label, href: nextAction.href } : null,\n    });\n  } catch (error) {\n    req.log.warn({ error, tenantId }, "onboarding assistant failed");\n    return res.status(502).json({ error: error instanceof Error ? error.message : "Não foi possível consultar o Agente de Implantação." });\n  }\n});\n\n'''
onboarding = onboarding.replace(assistant_anchor, assistant_route + assistant_anchor, 1)
onboarding_path.write_text(onboarding)

# ── Setup status must recognize Evolution QR too ─────────────────────────────
select_anchor = '''      metaPhoneNumberId: agentConfigsTable.metaPhoneNumberId,\n      metaAccessToken: agentConfigsTable.metaAccessToken,\n      instagramPageId: agentConfigsTable.instagramPageId,'''
select_replacement = '''      metaPhoneNumberId: agentConfigsTable.metaPhoneNumberId,\n      metaAccessToken: agentConfigsTable.metaAccessToken,\n      evolutionConnected: agentConfigsTable.evolutionConnected,\n      instagramPageId: agentConfigsTable.instagramPageId,'''
if select_anchor not in tenants:
    raise SystemExit('setup status select anchor not found')
tenants = tenants.replace(select_anchor, select_replacement, 1)

wa_old = '''  const whatsappConnected     = !!(agentConfig?.metaPhoneNumberId && agentConfig?.metaAccessToken);'''
wa_new = '''  const whatsappConnected     = !!((agentConfig?.metaPhoneNumberId && agentConfig?.metaAccessToken) || agentConfig?.evolutionConnected);'''
if wa_old not in tenants:
    raise SystemExit('setup status whatsapp boolean not found')
tenants = tenants.replace(wa_old, wa_new, 1)
tenants_path.write_text(tenants)

# ── Dashboard: turn checklist into implementation agent ──────────────────────
input_import_anchor = 'import { Progress } from "@/components/ui/progress";'
if input_import_anchor not in dashboard:
    raise SystemExit('dashboard input import anchor not found')
dashboard = dashboard.replace(input_import_anchor, input_import_anchor + '\nimport { Input } from "@/components/ui/input";', 1)

dashboard = dashboard.replace('''  { key: "whatsappConnected",         label: "WhatsApp conectado (Meta Cloud API)", href: "/configuracoes" },''', '''  { key: "whatsappConnected",         label: "WhatsApp conectado",                  href: "/onboarding/integracoes" },''', 1)

dashboard = dashboard.replace('''  const [dismissed, setDismissed] = useState(false);\n  const [collapsed, setCollapsed] = useState(false);\n''', '''  const [dismissed, setDismissed] = useState(false);\n  const [collapsed, setCollapsed] = useState(false);\n  const [assistantOpen, setAssistantOpen] = useState(false);\n  const [assistantQuestion, setAssistantQuestion] = useState("");\n  const [assistantAnswer, setAssistantAnswer] = useState<string | null>(null);\n  const [assistantLoading, setAssistantLoading] = useState(false);\n  const { token } = useAuth();\n''', 1)

pending_anchor = '''  const pendingItems = SETUP_ITEMS.filter((item) => !status[item.key as keyof SetupStatus]);\n\n  return ('''
pending_replacement = '''  const pendingItems = SETUP_ITEMS.filter((item) => !status[item.key as keyof SetupStatus]);\n  const nextItem = pendingItems[0] ?? null;\n\n  async function askImplementationAgent() {\n    if (!token) return;\n    const message = assistantQuestion.trim() || "Qual é o próximo passo mais importante para concluir minha implantação?";\n    setAssistantLoading(true);\n    setAssistantAnswer(null);\n    try {\n      const response = await fetch("/api/onboarding/assistant", {\n        method: "POST",\n        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },\n        body: JSON.stringify({ message }),\n      });\n      const data = await response.json() as { resposta?: string; error?: string };\n      if (!response.ok) throw new Error(data.error ?? "Não foi possível consultar o agente");\n      setAssistantAnswer(data.resposta ?? "Posso ajudar você a concluir a próxima etapa da implantação.");\n    } catch (error) {\n      setAssistantAnswer(error instanceof Error ? error.message : "Não foi possível consultar o Agente de Implantação.");\n    } finally {\n      setAssistantLoading(false);\n    }\n  }\n\n  return ('''
if pending_anchor not in dashboard:
    raise SystemExit('dashboard pending anchor not found')
dashboard = dashboard.replace(pending_anchor, pending_replacement, 1)

header_old = '''            <p className="font-semibold text-sm">\n              Configuração em andamento — {status.completedSteps}/{status.totalSteps} etapas concluídas\n            </p>\n            <p className="text-xs text-muted-foreground mt-0.5">\n              Complete o setup para ativar todos os recursos da plataforma.\n            </p>'''
header_new = '''            <p className="font-semibold text-sm flex items-center gap-1.5">\n              <Sparkles className="h-4 w-4 text-primary" />\n              Agente de Implantação — {status.completedSteps}/{status.totalSteps} etapas concluídas\n            </p>\n            <p className="text-xs text-muted-foreground mt-0.5">\n              Acompanho sua configuração e indico o próximo passo usando o status real da plataforma.\n            </p>'''
if header_old not in dashboard:
    raise SystemExit('dashboard setup header not found')
dashboard = dashboard.replace(header_old, header_new, 1)

old_footer = '''          {pendingItems.length > 0 && (\n            <div className="pt-2">\n              <Link\n                href="/guia-implantacao"\n                className="inline-flex items-center gap-1.5 text-xs text-primary hover:underline font-medium"\n              >\n                <BookOpen className="h-3 w-3" />\n                Ver guia completo de implantação\n              </Link>\n            </div>\n          )}'''
new_footer = '''          {nextItem && (\n            <div className="pt-3 mt-2 border-t border-primary/10 space-y-3">\n              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 rounded-lg bg-background/70 border p-3">\n                <div>\n                  <p className="text-xs text-muted-foreground">Próxima ação recomendada</p>\n                  <p className="text-sm font-medium">{nextItem.label}</p>\n                </div>\n                <Link href={nextItem.href}>\n                  <Button size="sm" className="w-full sm:w-auto">Fazer agora</Button>\n                </Link>\n              </div>\n\n              <Button\n                type="button"\n                variant="outline"\n                size="sm"\n                className="gap-2"\n                onClick={() => setAssistantOpen((current) => !current)}\n              >\n                <Sparkles className="h-4 w-4" />\n                {assistantOpen ? "Fechar Agente de Implantação" : "Perguntar ao Agente de Implantação"}\n              </Button>\n\n              {assistantOpen && (\n                <div className="rounded-lg border bg-background p-3 space-y-3">\n                  <div className="flex flex-col sm:flex-row gap-2">\n                    <Input\n                      value={assistantQuestion}\n                      onChange={(event) => setAssistantQuestion(event.target.value)}\n                      onKeyDown={(event) => {\n                        if (event.key === "Enter" && !assistantLoading) {\n                          event.preventDefault();\n                          void askImplementationAgent();\n                        }\n                      }}\n                      placeholder="Ex.: O que devo configurar primeiro?"\n                    />\n                    <Button\n                      type="button"\n                      onClick={() => void askImplementationAgent()}\n                      disabled={assistantLoading}\n                      className="shrink-0"\n                    >\n                      {assistantLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Perguntar"}\n                    </Button>\n                  </div>\n                  {assistantAnswer && (\n                    <div className="rounded-md bg-primary/5 border border-primary/10 px-3 py-2 text-sm whitespace-pre-wrap">\n                      {assistantAnswer}\n                    </div>\n                  )}\n                  <Link href="/faq" className="inline-flex items-center gap-1.5 text-xs text-primary hover:underline font-medium">\n                    <BookOpen className="h-3 w-3" />\n                    Abrir FAQ e ajuda\n                  </Link>\n                </div>\n              )}\n            </div>\n          )}'''
if old_footer not in dashboard:
    raise SystemExit('dashboard old guide footer not found')
dashboard = dashboard.replace(old_footer, new_footer, 1)

dashboard_path.write_text(dashboard)
print('Agente de Implantação patch applied')
